          </span>
          <span className={`chat-mode__option${funnyMode ? ' chat-mode__option--active' : ''}`}>
            Funny mode
          </span>
        </span>
      </label>
      <div className="chat-window__list" ref={listRef}>
        {!historyReady && (
          <p className="chat-window__placeholder">Loading…</p>
        )}
        {historyReady && messages.length === 0 && !loading && (
